action_input.code:
import json, csv
with open('json/event.json') as f: ev=json.load(f)
with open('json/expense.json') as f: ex=json.load(f)
with open('csv/budget.csv') as f: bu=list(csv.DictReader(f))
evt={r['event_id']:r['event_name'] for r in ev['records']}
ex_by_b={r['link_to_budget']:float(r['cost']) for r in ex['records']}
bu_ex={(b['link_to_event'],b['budget_id']) for b in bu}
cost={} 
for ev_id,b_id in bu_ex:
  if b_id in ex_by_b: cost[ev_id]=cost.get(ev_id,0)+ex_by_b[b_id]
min_id=min(cost,key=cost.get)
print(f"Event with lowest cost: {evt[min_id]}, cost={cost[min_id]}")
print('All event costs:',[(evt[k],cost[k]) for k in sorted(cost,key=lambda k:cost[k])])

